}

// สูตร LMS มาตรฐาน (WHO) — X_p จาก z-score, และย้อนกลับ z-score จาก X ที่วัดได้จริง
s.lmsToValue = (L, M, S, z) => (Math.abs(L) < 1e-8 ? M * Math.exp(S * z) : M * Math.pow(1 + L * S * z, 1 / L))
s.lmsToZ = (L, M, S, x) => (Math.abs(L) < 1e-8 ? Math.log(x / M) / S : (Math.pow(x / M, L) - 1) / (L * S))
s.BMI_SD_LINES = [-3, -2, -1.5, -1, 0, 1, 1.5, 2, 3]   // เส้น SD/Z-score ตาม BMI Chart for Thai Children by TSPE (thaipedendo.org)

// LMS ที่อายุใดๆ (เดือน) — interpolate เชิงเส้นระหว่างจุดที่มีจริง (ตารางไม่ได้ละเอียดทุกเดือนช่วง 2 ปีขึ้นไป)
s.lmsAt = (table, ageMo) => {
  if (ageMo <= table[0][0]) return table[0]
  const last = table[table.length - 1]
  if (ageMo >= last[0]) return last
  for (let i = 0; i < table.length - 1; i++) {
    const a = table[i], b = table[i + 1]
    if (ageMo >= a[0] && ageMo <= b[0]) {
      const t = (b[0] === a[0]) ? 0 : (ageMo - a[0]) / (b[0] - a[0])
      return [ageMo, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, a[3] + (b[3] - a[3]) * t]
    }
  }
  return last
}

s.ageMonthsBetween = (fromDate, toDate) => {
  if (!fromDate || !toDate) return null
  const a = field.dayjs(fromDate), b = field.dayjs(toDate)
  if (!a.isValid() || !b.isValid()) return null
  return b.diff(a, 'month', true)
}
s.currentAgeMonths = () => s.ageMonthsBetween(s.pt().birth_date, new Date())
s.isPediatricBmi = () => { const m = s.currentAgeMonths(); return m != null && m <= 228 }   // <= 19 ปี
s.bmiSexKey = () => (s.pt().p_gender === '2' ? 'girls' : 'boys')   // '2' = หญิง (genderLabel เดียวกับที่ใช้ทั้งไฟล์)

// ช่วงอายุของ "โปสเตอร์" ที่จะโชว์ — ยึดจุดตัดข้อมูลจริงที่ 60 เดือน (WHO สลับ curve fit ตรงนี้พอดี)
// เด็ก <5y เห็นกราฟ 0-5y, เด็ก >=5y เห็นกราฟ 5-19y (แบบเดียวกับโปสเตอร์จริงที่ TSPE ใช้แยกช่วงอายุ)
s.bmiChartAgeRange = () => { const m = s.currentAgeMonths(); return (m != null && m >= 60) ? [60, 228] : [0, 60] }

// เกณฑ์ overweight/obesity ของจริงจาก BMI Chart for Thai Children by TSPE (คนละเกณฑ์ระหว่างช่วงอายุ) —
// แสดงเป็นข้อมูลอ้างอิงในกราฟเท่านั้น ไม่เอาไปตัดสิน/ติดป้ายผลของคนไข้อัตโนมัติ (เหตุผลเดิม: อ่าน log 2026-08-03)
s.bmiDefinitionLines = () => {
  const [lo] = s.bmiChartAgeRange()
  return lo === 0
    ? ['Overweight: BMI SDS > +2 to +3', 'Obesity: BMI SDS > +3']
    : ['Overweight: BMI SDS > +1 to +2 or BMI ≥ 23-24.9 kg/m²', 'Obesity: BMI SDS > +2 or BMI ≥ 25 kg/m²']
}
// ความโปร่งใสเรื่อง data source: 0-5y ใช้ WHO ตรงกับที่ TSPE ใช้ แต่ 5-19y ต้นฉบับ TSPE ใช้ข้อมูลไทย
// (National Growth Reference 2020) คนละชุดกับ WHO Growth Reference ที่กราฟนี้ใช้ — บอกตรงๆ ในกราฟเลย
s.bmiSourceNote = () => {
  const [lo] = s.bmiChartAgeRange()
  return lo === 0
    ? 'BMI-for-age อ้างอิง: WHO Child Growth Standards (2006) — แหล่งเดียวกับที่ TSPE ใช้ในช่วงอายุนี้ · รูปแบบ/สีออกแบบให้ล้อตาม BMI Chart for Thai Children โดย TSPE'
    : 'BMI-for-age อ้างอิง: WHO Growth Reference (2007) — คำเตือน: กราฟต้นฉบับของ TSPE ช่วงอายุนี้ใช้ข้อมูล National Growth Reference 2020 (สำนักโภชนาการ) คนละชุดกับที่นี่ ตัวเลขอาจต่างเล็กน้อย'
}
s.bmiGrowthCurves = () => {
  const [lo, hi] = s.bmiChartAgeRange()
  return s.WHO_BMI_LMS[s.bmiSexKey()].filter((r) => r[0] >= lo && r[0] <= hi)
}

// จุด BMI จริงของเด็ก (อายุ ณ วันที่บันทึกแต่ละครั้ง, ไม่ใช่ index) — เฉพาะจุดที่อยู่ในช่วงโปสเตอร์ที่เลือก
s.bmiPatientPoints = () => {
  const [lo, hi] = s.bmiChartAgeRange()
  const bd = s.pt().birth_date
  return (s.bmiHistory || [])
    .map((r) => {
      const age = s.ageMonthsBetween(bd, r.created_at)
      return (age == null || r.bmi == null) ? null : { age, bmi: Number(r.bmi) }
    })
    .filter((p) => p && p.age >= lo && p.age <= hi)
    .sort((a, b) => a.age - b.age)
}

// วาดกราฟ BMI-for-age เอง — เส้นอ้างอิง P3/P15/P50/P85/P97 (จาก LMS จริงข้างบน) + เส้น BMI จริงของเด็กทับ
s.bmiApexOptions = () => {
  const curves = s.bmiGrowthCurves()
  const [lo, hi] = s.bmiChartAgeRange()
  const isGirl = s.bmiSexKey() === 'girls'
  const bg = isGirl ? '#fbe4ee' : '#e1f0f8'
  const gridColor = isGirl ? '#f2c2d9' : '#bfe0ef'

  const sdLines = s.BMI_SD_LINES
  const sdSeries = sdLines.map((z) => ({
    name: (z > 0 ? '+' + z : String(z)) + ' SD',
    data: curves.map((r) => ({ x: r[0], y: Math.round(s.lmsToValue(r[1], r[2], r[3], z) * 100) / 100 }))
  }))
  const ptPoints = s.bmiPatientPoints()
  const patientSeries = {
    name: 'BMI คนไข้',
    data: ptPoints.map((p) => ({ x: p.age, y: p.bmi }))
  }
  const series = sdSeries.concat([patientSeries])

  return {
    chart: {
      type: 'line',
      height: '100%',
      background: bg,
      toolbar: { show: true, tools: { download: false } },
      zoom: { enabled: true, type: 'x', autoScaleYaxis: true },
      animations: { enabled: false }
    },
    colors: sdLines.map(() => '#222222').concat(['#626aef']),
    stroke: {
      width: sdLines.map((z) => (z === 0 ? 3 : 1.3)).concat([3]),
      curve: 'straight'
    },
    markers: { size: sdLines.map(() => 0).concat([4]) },
    dataLabels: { enabled: false },
    grid: { borderColor: gridColor },
    legend: { show: true, position: 'right', fontSize: '11px', offsetY: 10 },
    tooltip: {
      shared: false,
      custom: function (opt) {
        const ser = opt.w.config.series[opt.seriesIndex]
        const pt = ser.data[opt.dataPointIndex]
        const ageYears = (pt.x / 12).toFixed(1)
        const color = (opt.w.config.colors && opt.w.config.colors[opt.seriesIndex]) || '#222222'
        return '<div style="background:#ffffff;color:#222222;padding:6px 10px;border-radius:4px;font-size:12px;border:1px solid #cccccc;box-shadow:0 2px 6px rgba(0,0,0,0.25);white-space:nowrap;">' +
          '<div style="font-weight:600;margin-bottom:2px;">' + ageYears + ' ปี</div>' +
          '<div><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' + color + ';margin-right:4px;"></span>' + ser.name + ': ' + pt.y + '</div>' +
          '</div>'
      }
    },
    xaxis: {
      type: 'numeric',
      min: lo,
      max: hi,
      title: { text: 'อายุ (ปี)' },
      labels: { formatter: (v) => (v / 12).toFixed(0) },
      tooltip: { enabled: false }
    },
    yaxis: {
      title: { text: 'BMI (kg/m²)' },
      decimalsInFloat: 1
    },
    series: series
  }
}

s.bmiApexLoadTries = 0
s.mountBmiChart = () => {
  if (!s.bmiChartVisible || !s.isPediatricBmi() || !s.bmiHistory || !s.bmiHistory.length) return
  const el = s.bmiChartElNode
  const hasLib = (typeof ApexCharts !== 'undefined')
  if (s.bmiApexLoadTries === 0) {
    console.log('[BMI chart] mount attempt: container=' + (el ? 'found' : 'MISSING') + ' ApexCharts=' + (hasLib ? 'ready' : 'MISSING'))
  }
  if (!el || !hasLib) {
    s.bmiApexLoadTries++
    if (s.bmiApexLoadTries > 120) {
      const reason = !el ? 'ไม่พบ container element' : 'ApexCharts library ไม่พร้อมใช้งาน'
      console.error('[BMI chart] gave up after ' + s.bmiApexLoadTries + ' tries — container=' + (el ? 'found' : 'MISSING') + ' ApexCharts=' + (hasLib ? 'ready' : 'MISSING'))
      if (el) el.innerHTML = '<div style="padding:16px;color:#c0392b;font-size:12px;">โหลดกราฟไม่สำเร็จ: ' + reason + '</div>'
      return
    }
    setTimeout(s.mountBmiChart, 150)
    return
  }
  s.bmiApexLoadTries = 0
  if (s.bmiApexInstance) { s.bmiApexInstance.destroy(); s.bmiApexInstance = null }
  try {
    s.bmiApexInstance = new ApexCharts(el, s.bmiApexOptions())
    s.bmiApexInstance.render()
    console.log('[BMI chart] rendered ok')
  } catch (e) {
    el.innerHTML = '<div style="padding:16px;color:#c0392b;font-size:12px;">วาดกราฟผิดพลาด: ' + (e && e.message ? e.message : String(e)) + '</div>'
    console.error('[BMI chart] render error', e)
  }
}

s.bmiLatestZ = () => {
  const list = s.bmiHistory || []
  const rec = list.length ? list[list.length - 1] : null   // loadBmiHistory เรียง created_at ASC
  if (!rec || rec.bmi == null) return null
  const age = s.ageMonthsBetween(s.pt().birth_date, rec.created_at)
  if (age == null) return null
  const [, L, M, S] = s.lmsAt(s.WHO_BMI_LMS[s.bmiSexKey()], age)
  return { z: s.lmsToZ(L, M, S, Number(rec.bmi)), age, bmi: Number(rec.bmi) }
}

s.bmiHistoryLabels = () => (s.bmiHistory || []).map((r) => field.dayjs(r.created_at).format('DD/MM'))
s.bmiHistoryChartBmi = () => s.svgLineChart([
  { name: 'BMI', color: '#626aef', values: (s.bmiHistory || []).map((r) => (r.bmi == null ? null : Number(r.bmi))) }
], s.bmiHistoryLabels(), '')
s.bmiHistoryChartWeight = () => s.svgLineChart([
  { name: 'น้ำหนัก', color: '#e6a23c', values: (s.bmiHistory || []).map((r) => (r.weight == null ? null : Number(r.weight))) }
], s.bmiHistoryLabels(), ' กก.')
s.bmiHistoryChartStature = () => s.svgLineChart([
  { name: 'ส่วนสูง', color: '#67c23a', values: (s.bmiHistory || []).map((r) => (r.stature == null ? null : Number(r.stature))) }
], s.bmiHistoryLabels(), ' ซม.')

// ---- กราฟ Vital Sign (BP/Pulse/Temp/RR) — เปิดจากไอคอน TrendCharts ข้างดินสอ Vital Sign ----
s.vsChartVisible = false
s.openVsChart = () => { s.vsChartVisible = true; s.loadVsHistory() }
s.closeVsChart = () => { s.vsChartVisible = false }
s.vsTableRows = () => {
  let list = (s.vsHistory || []).slice()
  if (s.vsFilterMode.type === 'count') {
    list = list.slice(-s.vsFilterMode.value)
  } else {
    list = list.filter((r) => field.dayjs().diff(field.dayjs(r.created_at), 'month', true) <= s.vsFilterMode.value)
  }
  return list.reverse().map((r) => {
    const d = field.dayjs(r.created_at)
    return {
      rec: r,
      dateLabel: d.format('DD/MM/') + (d.year() + 543) + d.format(' HH:mm'),
      vn: (r.vid && r.vid.vn) || '-'
    }
  })
}

// ---- timer เวลาตรวจ — นับจาก start_at (stamp ตอนกดเริ่มตรวจ) เท่านั้น ----
// ยังไม่เริ่มตรวจ = '--:--' (ไม่ fallback checkin_at — นั่นคือเวลารอ ไม่ใช่เวลาตรวจ)
s.examClock = '--:--'
s.tickExam = () => {
  const t = s.tran && s.tran.start_at
  if (!t) { s.examClock = '--:--'; return }
  const sec = Math.max(0, Math.floor((new Date() - new Date(String(t).replace(' ', 'T'))) / 1000))
  const h = Math.floor(sec / 3600)
  const mm = String(Math.floor((sec % 3600) / 60)).padStart(2, '0')
  const ss = String(sec % 60).padStart(2, '0')
  s.examClock = h > 0 ? h + ':' + mm + ':' + ss : mm + ':' + ss
}

options.onMounted:
const form = this.getFormRef()
if (form && form.$examTran) {
  this.vueState.setTran(form.$examTran)
} else {
  // เปิดแท็บ EMR ตรงๆ โดยยังไม่กด EMR จากคิว → ซ่อนโซน SOAP
  const box = this.getFieldRef('emr_box')
  if (box) box.hide()
}

// เริ่มเดินนาฬิกา — กัน interval ซ้อนกรณี re-mount
const s = this.vueState
if (s.examTimerId) clearInterval(s.examTimerId)
s.tickExam()
s.examTimerId = setInterval(s.tickExam, 1000)

options.onCreated:
const s = this.vueState
const field = this
const CONSULT_FORM = '6a482ea68ca8083d715e3498'
const TRAN_FORM = '6a461235e521219e514d1c4b'   // visit_tran — re-fetch หลังตอบ consult

s.tran = null
// ฝั่งรับ (clinic===unit_to) — คืน consult ทุก status ที่ recompute เก็บ (accept / complete+reply)
s.ci = () => {
  const t = s.tran
  if (!t || !t.consult_info) return null
  const c = t.consult_info
  const dest = c.clinic && t.unit_to && String(c.clinic) === String(t.unit_to.value)
  return dest ? c : null
}
s.fromLabel = () => (s.tran && s.tran.unit_from && s.tran.unit_from.label) || '-'
s.priorityText = () => { const c = s.ci(); return c ? ({ '20': 'เร่งด่วน', '30': 'STAT' })[String(c.priority)] || '' : '' }
s.priorityType = () => { const c = s.ci(); return c ? ({ '20': 'warning', '30': 'danger' })[String(c.priority)] || 'info' : 'info' }
s.load = (tran) => { s.tran = tran || null }

// เปิดฟอร์ม Consult (ตอบ/แก้คำตอบ) — send-back ทำที่ My Room ไม่ใช่ตรงนี้
s.answer = () => {
  const c = s.ci(); if (!c) return
  const form = field.getFormRef()
  const tranId = (s.tran && s.tran._id) ? String(s.tran._id) : ''
  const visitId = (s.tran && s.tran.vid && s.tran.vid.value) ? String(s.tran.vid.value) : ''
  form.openForm(CONSULT_FORM, String(c.consult_id), visitId, null, {
    afterSaveCallback: () => {
      form.subFormClose()
      // consult-sync-tran (api_onevent, ถูก await ตอน save) เพิ่งอัปเดต tran.consult_info ใน DB แล้ว
      // banner ผูกกับ snapshot tran เดิม → re-fetch tran ตัวเดิม แล้ว re-feed ผ่าน opd_card.setTran
      // (setTran กระจายให้ banner + consult_box + registry สดพร้อมกัน — จุดเดียวจบ)
      if (!tranId) return
      form.userState.crudGetAll({
        sdProvider: {
          providerId: TRAN_FORM,
          providerType: 'FORM',
          params: { tid: tranId },
          options: { where: "`_id` = CONVERT(:tid, 'objectId')", limit: 1, page: 1 }
        },
        totalEnable: false
      }, (res) => {
        const fresh = (res.data && res.data[0]) || null
        const opd = field.getFieldRef('opd_card')
        if (fresh && opd && opd.vueState && opd.vueState.setTran) opd.vueState.setTran(fresh)
      })
    }
  })
}

/**
 * order_card (ฟอร์ม PIS ห้องยา 6a7a7736935ed08882467002) · onCreated — การ์ดใบสั่งยา "ฝั่งห้องยา"
 *
 * หน้าที่: ทางเดินของใบทั้งวงจรในห้องยา รวมอยู่ที่การ์ดนี้ที่เดียว
 *   ① เห็นใบของวิสิทที่กำลังทำอยู่ + สถานะ/ป้ายชำระ
 *   ② ปุ่มบันได จัดยา → ชำระ(เทส) → จ่ายยา  ③ แก้ใบก่อนจัดยา  ④ ออกใบเองในนามเภสัช
 *
 * 🔴 คนละไฟล์กับการ์ดหมอ (cpoe/widget-order-card.*) โดยตั้งใจ — ห้ามแก้ของหมอให้ทำสองหน้าที่
 *    ฝั่งหมอ = ส่ง/ยกเลิก/ลบใบร่าง · ฝั่งนี้ = รับช่วงหลังใบถูกส่งแล้ว กติกาปุ่มคนละชุดกัน
 *
 * 🔴 ชื่อ `ordLoad(visitId, tran)` เป็นสัญญากับ `opd_card.setTran` ของฟอร์มนี้ (เรียกตอนเปลี่ยนคนไข้)
 *    เปลี่ยนชื่อเมื่อไหร่ = เลือกคนไข้แล้วการ์ดไม่โหลด โดยไม่มี error ให้เห็น
 * 🔴 การ์ดไม่ query ข้อมูลคนไข้เอง — หยิบจาก opd_card ที่โหลดไว้แล้ว (แหล่งเดียวกับฝั่งหมอ)
 * 🔴 ปุ่มเป็น sync handler ⇒ รับผลผ่าน callback ของ runProcess เท่านั้น
 */

const s = this.vueState;
const field = this;

const DRUG_ORDER_FORM_ID = '6a70b8cd74be9b0d6e2dca74'; // Drug Order (form_ui) — จอสั่งยาตัวเดียวกับหมอ
const LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list (อ่านใบ + flag ปุ่มทุกตัว)
const PREPARE_PROC = '6a7a86878d98467159125d08'; // pis-order-prepare  · sent/accepted → prepared
const PAID_PROC = '6a7a86886d5c9fcbc7f9a7bc'; // pis-order-paid     · prepared → ready
const DISPENSE_PROC = '6a7a8688d1abb9712d65f0c2'; // pis-order-dispense · ready → dispensed
const REVERT_PROC = '6a7b2fb1ec4ad5e37a2aca42'; // pis-order-revert   · prepared/ready → accepted (C17)
const RETURN_PROC = '6a7becc4166ab55b25eafb6a'; // pis-order-return   · รับยาคืนเข้าคลัง (C19)
const VISIT_PROVIDER = '6a40fdec4b6dfdf45acbfbce'; // ฟอร์ม Visit → zdata_visit (อ่านสิทธิ์)
/* ฉลากยาติดซอง (C21 · พี่สั่ง 2026-09-01 "ปริ้นทั้งใบ") — report `PIS · ฉลากยา (8x6 cm)`
   ต้นทางอยู่ที่ sdform/pis/report/report-drug-label.json + sql-drug-label.json
   🔴 id นี้เกิดตอน deploy (scripts/deploy-report.mjs) — ค่าปัจจุบันอ่านได้จาก sdform/pis/report/report-ids.cjs
      ขึ้น instance ใหม่ = id ใหม่ ⇒ ต้อง deploy report แล้วเอา id จากไฟล์นั้นมาใส่ตรงนี้ ไม่งั้นปุ่มกดแล้วเงียบ */
const LABEL_REPORT = '6a96c0fd6307e3284ebd49bc';

/* ══ state ════════════════════════════════════════════════════════════════ */
s.ordList = [];
s.ordLoading = false;
s.ordErr = '';
s.ordHidden = 0; // ใบของวิสิทที่ไม่มียาเลย (ใบแลบ/เอกซเรย์) — ซ่อนไว้ แต่บอกจำนวนที่ท้ายการ์ด
s.ordVid = null; // visit _id ปัจจุบัน — เซ็ตผ่าน ordLoad จาก opd_card
s.ordTran = null; // Visit Tran ทั้งแถว (ใช้ประกอบ patient context ตอนเปิดจอสั่งยา)
s.ordOpenRow = {};
s.ordDirty = false; // จอสั่งยาแตะใบใน DB แล้วหรือยัง — ตัวตัดสินว่าตอนปิด popup ต้องโหลดใหม่ไหม
/* order_id → ชื่อ action ที่กำลังยิง ('prepare'/'pay'/'dispense')
   🔴 ใบเดียวใช้ตัวเดียวกันทั้งสามปุ่ม — ระหว่างรอ process ใบนั้นต้องกดอะไรไม่ได้เลย
      (ปุ่มบันไดอยู่บนใบเดียวกัน กดจัดยาแล้วรีบกดชำระ = ยิงบนสถานะที่ยังไม่เปลี่ยน) */
s.ordAct = {};

/* ══ ป้ายสถานะ — ชุดเดียวกับการ์ดหมอ/design D6 ═══════════════════════════
   🔴 ค่าที่ไม่รู้จักต้องโชว์ค่าดิบ ห้ามแปลงเป็น "ร่าง" — ใบที่สถานะเพี้ยนต้องมองเห็นได้จากจอ */
const STATUS = {
	draft: { label: 'ร่าง', color: 'info' },
	sent: { label: 'ส่งห้องยาแล้ว', color: 'warning' },
	accepted: { label: 'ห้องยารับแล้ว', color: 'warning' },
	prepared: { label: 'จัดยาแล้ว', color: 'warning' },
	ready: { label: 'พร้อมจ่าย', color: 'success' },
	dispensed: { label: 'จ่ายยาแล้ว', color: 'success' },
	returned: { label: 'คืนยา', color: 'danger' },
	cancelled: { label: 'ยกเลิก', color: 'info' },
	reversed: { label: 'กลับรายการ', color: 'danger' },
};
s.ordStatus = (o) => {
	const raw = String((o && o.current_status) || '');
	return STATUS[raw] || { label: raw || '—', color: 'danger' };
};

/* ป้ายชำระ (a2 · พี่เคาะ 2026-08-11) — อ่านจากสถานะใบผ่าน flag `paid` ของ process
   ไม่มี field paid_status แยกในระบบ (design D6) ⇒ ห้ามคิดเงื่อนไขเองที่จอ */
s.ordPaidTag = (o) => (o && o.paid ? { label: 'ชำระแล้ว', color: 'success' } : { label: 'ยังไม่ชำระ', color: 'info' });

s.ordMoney = (n) => '฿' + Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// created_at เป็น "YYYY-MM-DD HH:mm:ss" — ใบของวิสิทเดียวกันเกิดวันเดียวกันเกือบเสมอ จึงโชว์แค่เวลา
s.ordTime = (v) => {
	const t = String(v || '');
	return t.length >= 16 ? t.slice(11, 16) + ' น.' : t;
};

s.ordToggle = (id) => {
	s.ordOpenRow[id] = !s.ordOpenRow[id];
};

/* ══ มุมมอง "จัดยา" ของรายการในใบ (C20 · พี่เคาะ 2026-09-01) ═══════════════
   จอนี้คือที่ที่เภสัชจัดยาจริง ⇒ ต้องอ่านได้ครบจากการ์ดโดยไม่ต้องเปิดใบ:
   ชื่อ+tag · จำนวน+หน่วยจ่าย · วิธีใช้ (sig) · ราคา/เบิกได้/จ่ายเอง · คำเตือนรายตัว
   🔴 ทุกตัวเป็นการ "จัดรูป" ค่าที่ process ส่งมาแล้วเท่านั้น — ห้ามคิดราคา/ประกอบฉลากเองที่จอ
      (ฉลากประกอบที่จอสั่งยาตอนบันทึก · ราคาคิดที่ cpoe-price-calc — คิดซ้ำที่นี่ = สองจอพูดไม่ตรงกัน) */

/* รายการนี้เป็นยาไหม — 🔴 ห้าม "ไม่รู้ = ปล่อยผ่าน" เด็ดขาด
   เคสจริง 2026-09-01: widget ขึ้นจอก่อน process รุ่นใหม่ ⇒ ไม่มี `is_med` มาเลย
   fallback เดิมปล่อยผ่านทุกตัว ⇒ ใบแลบขึ้นเป็น "ยา" พร้อมบรรทัด "ไม่ได้ระบุวิธีใช้" ทั้งใบ
   ⇒ ตัดสินจากช่องที่ process **รุ่นเก่าก็ส่งมาแล้ว** (`item_type_code` = service_type ของรายการ)
      แล้วค่อยเสริมด้วย item_source เมื่อ process รุ่นใหม่ขึ้นแล้ว */
const isMedItem = (it) => {
	if (!it) return false;
	if (it.is_med === true) return true;
	if (String(it.item_source || '') === 'drug') return true;
	if (it.is_med === false) return false;
	return String(it.item_type_code || '') === 'med'; // process รุ่นเก่า — ยังแยกยาออกจากแลบได้
};

s.ordMedItems = (o) => ((o && o.items) || []).filter(isMedItem);
// รายการที่ไม่ใช่ยาในใบผสม — ไม่โชว์เป็นบรรทัด แต่ต้องบอกจำนวนไว้ ไม่งั้นเภสัชนึกว่าใบตกหล่น
s.ordOtherCount = (o) => ((o && o.items) || []).filter((it) => !isMedItem(it)).length;
// จำนวนยาในใบ — ใช้ค่าจาก process ถ้ามี ไม่มีก็นับจากรายการที่ส่งมา (จอต้องพูดถูกทั้งสองรุ่น)
s.ordMedCount = (o) => (o && typeof o.med_count === 'number' ? o.med_count : s.ordMedItems(o).length);

/* ฉลากวิธีใช้ — ยึดฉลากไทยก่อน (เป็นตัวที่ติดซองจริง) แล้วค่อยฉลากอังกฤษ
   ใบเก่าที่ไม่มีทั้งคู่ ประกอบจากชิ้นส่วนเท่าที่มี ⇒ ดีกว่าโชว์ช่องว่างให้เภสัชเดาเอง */
s.ordSig = (it) => {
	const g = (it && it.sig) || null;
	if (!g) return '';
	if (g.label_th) return g.label_th;
	if (g.label) return g.label;
	const parts = [];
	if (g.dose) parts.push('ครั้งละ ' + g.dose + (g.unit ? ' ' + g.unit : ''));
	if (g.freq) parts.push(g.freq);
	if (g.timing) parts.push(g.timing);
	if (g.route) parts.push('(' + g.route + ')');
	if (g.duration) parts.push('× ' + g.duration + ' วัน');
	return parts.join(' ');
};
s.ordSigExtra = (it) => {
	const g = (it && it.sig) || null;
	if (!g) return [];
	const out = [];
	if (g.indication) out.push('ข้อบ่งใช้: ' + g.indication);
	(g.labels || []).forEach((x) => out.push(x)); // ฉลากช่วย (ห้ามขับรถ ฯลฯ) — ต้องเห็นตอนจัด ไม่ใช่ตอนพิมพ์
	if (g.note) out.push(g.note);
	return out;
};

// จำนวน + หน่วยจ่าย — "14" เฉย ๆ จัดผิดได้ (14 เม็ด vs 14 ขวด)
s.ordQty = (it) => String((it && it.quantity) || 0) + (it && it.dispense_unit ? ' ' + it.dispense_unit : '');

/* บรรทัดเงินของรายการ — เภสัชต้องบอกคนไข้ได้ว่า "เบิกได้เท่าไหร่ จ่ายเองเท่าไหร่"
   🔴 ยอดที่ไม่มีค่า (null) ต่างจาก 0 — null = ใบเก่าที่ไม่ได้แยกช่องไว้ ⇒ ไม่ต้องโชว์
      แปลง null เป็น 0 เมื่อไหร่ ใบเก่าจะอ่านว่า "เบิกไม่ได้เลย" ทั้งที่ระบบแค่ไม่รู้ */
s.ordHas = (v) => v !== null && v !== undefined && v !== '';
s.ordItemAlerts = (it) => (it && it.alerts) || [];
s.ordAlertColor = (a) => (String((a && a.level) || '') === 'warn' ? 'var(--el-color-warning)' : 'var(--el-color-danger)');

// ใบที่ห้องยายังต้องทำอะไรต่อ — ใช้ตัดสินว่าจะกางรายการให้เลยไหม
const actionable = (o) => !!(o && (o.can_prepare || o.can_pay || o.can_dispense));

/* ใบนี้เป็นงานห้องยาไหม (พี่เคาะ 2026-09-01) — ใบ Lab/X-ray ของหมอต้องไม่โผล่ที่นี่
   🔴 ตัดสินจากรายการก่อนเสมอ (ใบผสมยา+แลบต้องไม่หาย) แล้วค่อยดูหัวใบ
   🔴 ใบที่รายการยังไม่ถูกส่งมา (ใบร่างที่บันทึกไม่ครบ) ยึดหัวใบ = med เท่านั้น
      "ไม่รู้แล้วโชว์ไว้ก่อน" ทำให้ใบแลบขึ้นเป็นยาทั้งจอมาแล้ว (เจอจริง 2026-09-01) */
const hasMedOrder = (o) => {
	if (!o) return false;
	if (o.has_med === true) return true;
	if (Array.isArray(o.items) && o.items.length) return o.items.some(isMedItem);
	return String(o.service_type_code || '') === 'med';
};

/* ══ โหลดใบของวิสิท ═══════════════════════════════════════════════════════
   🔴 ชื่อนี้ถูกเรียกจาก opd_card.setTran ของฟอร์ม PIS — ห้ามเปลี่ยน signature
   เรียกจาก: opd_card (เปลี่ยนคนไข้) · onMounted (เข้าแท็บทีหลัง) · หลังปิดจอสั่งยา · หลังกดปุ่มสำเร็จ */
s.ordLoad = (visitId, tran) => {
	s.ordVid = visitId ? String(visitId) : null;
	if (tran !== undefined) s.ordTran = tran || null;
	s.ordList = [];
	s.ordErr = '';
	s.ordOpenRow = {};
	s.ordAct = {}; // ปุ่มที่ค้าง busy ของรายการเก่าต้องหายไปพร้อมลิสต์ ไม่งั้นใบใหม่โดนล็อกตามไปด้วย
	if (!s.ordVid) return;
	const form = field.getFormRef();
	if (!form) return;
	s.ordLoading = true;
	form.userState.runProcess(
		LIST_PROC,
		/* 🔴 `full_items` = ขอรายการครบทุกบรรทัด (default ของ process ส่งแค่ 8 แรก ซึ่งพอสำหรับการ์ดหมอ)
		   ห้องยาเห็นไม่ครบ = จัดตกรายการ ⇒ จอนี้ขอครบเสมอ ไม่มีโหมดย่อ */
		{ visit_id: s.ordVid, full_items: true },
		(res) => {
			s.ordLoading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ ไม่ใช่ errCb — ต้องเช็คเอง
			if (!d.success) {
				s.ordErr = d.message || 'อ่านใบสั่งยาไม่สำเร็จ';
				return;
			}
			/* ══ ห้องยาเห็นเฉพาะใบที่มียา (พี่เคาะ 2026-09-01) ═══════════════════════
			   วิสิทเดียวกันมีใบ Lab/X-ray ของหมอปนอยู่ (เลขใบ R…) ซึ่งห้องยาทำอะไรกับมันไม่ได้เลย
			   แต่การ์ดเดิมยังขึ้นปุ่ม "จัดยา" ให้ ⇒ เภสัชกดเดินสถานะใบแลบได้จริง
			   🔴 ตัดสินจาก `has_med` (นับจากรายการ) ไม่ใช่ service_type ของหัวใบ — ใบผสมยา+แลบต้องไม่หาย
			   🔴 ใบที่ process รุ่นเก่ายังไม่ส่ง flag มา (undefined) ให้ผ่านไว้ก่อน — ซ่อนใบยาผิดอันตรายกว่าโชว์ใบแลบเกิน
			   🔴 ใบยาที่รายการหายหมด (บันทึกไม่ครบ) has_med = false เหมือนกัน ⇒ ปล่อยผ่านด้วย
			      หัวใบเป็น med — ใบกลุ่มนี้คือใบที่ต้องเห็นที่สุด การ์ดมีบรรทัดเตือน "บันทึกไม่ครบ" รออยู่แล้ว */
			const all = Array.isArray(d.orders) ? d.orders : [];
			s.ordList = all.filter(hasMedOrder);
			s.ordHidden = all.length - s.ordList.length;
			/* ใบที่ห้องยาต้องลงมือ = สิ่งที่เภสัชต้องเห็นรายการยาทันที ⇒ กางให้เลยทุกใบ
			   (ต่างจากฝั่งหมอที่กางเฉพาะใบร่างใบเดียว — ห้องยามักมีหลายใบต่อวิสิทพร้อมกัน) */
			s.ordList.forEach((o) => {
				if (actionable(o)) s.ordOpenRow[o.order_id] = true;
			});
			/* ใบเดียวในวิสิท = กางเลย ไม่ต้องให้กดก่อน (พี่สั่ง 2026-09-01)
			   ไม่มีอะไรให้เลือกอยู่แล้ว การพับไว้คือคลิกที่เสียเปล่าหนึ่งครั้งของทุกคนไข้
			   🔴 รวมใบร่าง/ใบยกเลิกด้วยโดยตั้งใจ — เภสัชต้องเห็นว่าใบเดียวที่มีคืออะไร ถึงจะรู้ว่าต้องทำอะไรต่อ */
			if (s.ordList.length === 1) s.ordOpenRow[s.ordList[0].order_id] = true;
		},
		(err) => {
			s.ordLoading = false;
			s.ordErr = 'อ่านใบสั่งยาไม่สำเร็จ: ' + ((err && err.message) || err);
		},
	);
};

s.ordReload = () => s.ordLoad(s.ordVid, undefined);

/* ══ patient context ที่จอสั่งยาต้องได้ครบ ════════════════════════════════
   🔴 จอสั่งยา "ห้าม query ซ้ำ" — ข้อมูลคนไข้/วิสิท/สิทธิ์/vitals ต้องส่งครบจากที่นี่ (D4.4)
      ตารางแปลงค่า (เพศ · หมู่เลือด · ชนิดบริการ · ระดับ warn/danger ของ vital) อยู่ที่ opd_card
      ที่เดียว — หยิบมาใช้ ห้ามทำชุดของตัวเอง ไม่งั้นวันหนึ่งสองจอจะเตือนคนละแบบ
   🔴 ส่งทาง `params` ไม่ใช่ `initData` — form_ui ที่มีแต่ vue-ui ตัด initData ทิ้งใน buildDataModel */
const ptContext = () => {
	const form = field.getFormRef();
	const card = field.getFieldRef('opd_card');
	const cs = (card && card.vueState) || {};
	const tran = s.ordTran || cs.tran || (form && form.$examTran) || null;
	const visit = (tran && tran.vid) || null;
	if (!visit) return null;

	const pt = visit.pid || {};
	const bmi = cs.bmiRec || {};
	const vs = cs.vsRec || {};
	const lvl = (name) => {
		if (typeof cs.vsClass !== 'function') return '';
		const c = cs.vsClass(name);
		return c === 'is-danger' ? 'bad' : c === 'is-warning' ? 'warn' : '';
	};
	const vital = (value, level) => (value === null || value === undefined || value === '' ? null : { value: value, level: level || '' });
	const bpValue = vs.bp_h && vs.bp_l ? String(vs.bp_h) + '/' + String(vs.bp_l) : '';
	const bpLevel = typeof cs.bpClass === 'function' ? (cs.bpClass() === 'is-danger' ? 'bad' : cs.bpClass() === 'is-warning' ? 'warn' : '') : '';

	return {
		person_id: visit.xtbxlv1_xfx_id ? String(visit.xtbxlv1_xfx_id) : '',
		hn: pt.hn || '',
		full_name: typeof cs.ptName === 'function' ? cs.ptName() : [pt.p_fname, pt.p_lname].filter(Boolean).join(' '),
		sex: typeof cs.genderLabel === 'function' ? cs.genderLabel() : '',
		age: pt.age == null ? '' : pt.age,
		blood_group: typeof cs.aboLabel === 'function' ? cs.aboLabel() : '',
		p_pic: pt.p_pic || null,
		allergy_tags: (tran && tran.allergy_tags) || [],
		visit_id: String(visit.value || visit._id || ''),
		vn: visit.vn || '',
		visit_type: typeof cs.serviceTypeLabel === 'function' ? cs.serviceTypeLabel() : '',
		visit_datetime: typeof cs.visitTime === 'function' ? cs.visitTime() : visit.visit_date || '',
		visit_clinic: (visit.visit_clinic || {}).label || '',
		visit_doctor: (visit.visit_doctor || {}).label || '',
		dx_summary: '',
		weight: bmi.weight == null ? '' : bmi.weight,
		height: bmi.stature == null ? '' : bmi.stature, // 🔴 ฟอร์ม BMI ใช้ชื่อ stature ไม่ใช่ height
		bmi: bmi.bmi == null ? '' : bmi.bmi,
		bsa: bmi.bsa == null ? '' : bmi.bsa,
		bp: vital(bpValue, bpLevel),
		pr: vital(vs.pulse, lvl('pulse')),
		temp: vital(vs.temp, lvl('temp')),
		rr: vital(vs.rr, lvl('rr')),
		service_type: 'med',
		inscl_hos: Array.isArray(visit.inscl_hos) ? visit.inscl_hos : [],
	};
};

/* เปิดจอสั่งยา — extra = { order_id } เมื่อเป็นการเปิดใบเดิมมาแก้

   🔴 ไม่ส่ง `cosign_user_id` ทั้งสองทาง (b5 · พี่เคาะ 2026-08-11)
      ใบที่เภสัชออกเอง ผู้สั่งต้องเป็นเภสัชคนกด ไม่ใช่หมอ — cpoe-order-save default = คนกดอยู่แล้ว
      · เปิดใบเดิมมาแก้ จอจะเซ็ตผู้สั่งกลับจาก `head.cosign_user_id` ของใบเอง (ผู้สั่งเดิมไม่เด้ง)
   🔴 ส่ง `pis_mode: true` ไปด้วย (C13 · พี่เคาะ "ปิดแบบเห็นร่องรอย" 2026-08-11)
      จอสั่งยาปกติ auto-select ผู้สั่ง = ตัวเอง ถ้าคนล็อกอินอยู่ในลิสต์หมอ
      ⇒ user ที่ถือทั้ง PHARMA + DOCTOR (เช่น `admin`) เปิดจากห้องยา ใบจะลงชื่อตัวเองเป็นผู้สั่งเงียบ ๆ
      ธงนี้บอกจอว่า "เปิดจากห้องยา" ⇒ เว้นช่องผู้สั่งไว้ให้เลือกเอง — **เลือกได้ตามปกติ ไม่ได้ล็อก**
      (ใบที่ผู้สั่ง ≠ คนกด การ์ดจะขึ้นป้าย "ออกใบโดย …" จาก flag `issued_by_other` ของ cpoe-order-list)

   🔴 refresh เฉพาะตอนที่ "ใบเปลี่ยนจริง" — cancelCallback เป็นทางออกทางเดียวของ popup
      ทั้ง "กดปิดเฉย ๆ" และ "บันทึกแล้วปิด" ⇒ ให้จอเป็นคนบอกผ่าน callback ที่ฝากไปกับ params */
const openScreen = (ctx, extra) => {
	const form = field.getFormRef();
	s.ordDirty = false;
	form.openForm(DRUG_ORDER_FORM_ID, '', String(ctx.visit_id), null, {
		backdrop: false, // ใบยาว — กดพลาดนอกกล่องแล้วปิดทิ้ง = เสียของที่เลือกไว้
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams, ctx, extra || {}, {
			pis_mode: true, // เปิดจากห้องยา — จอจะไม่ auto-select ผู้สั่งเป็นตัวเอง (C13)
			on_order_saved: () => {
				s.ordDirty = true;
			},
		}),
		// 🔴 ใส่ cancelCallback เอง = ทับ default ⇒ ต้อง subFormClose() เองด้วย
		cancelCallback: () => {
			form.subFormClose();
			if (!s.ordDirty) return; // ปิดเฉย ๆ — รายการในการ์ดยังตรงกับ DB อยู่แล้ว
			s.ordDirty = false;
			s.ordReload();
		},
	});
};

/* สิทธิ์ของวิสิท (D9 ข้อ 1) — joiner `vid` ของ Visit Tran ยังไม่ได้ดึง inscl_hos[] มาให้
   ไม่มีสิทธิ์ = จอคิดเป็นชำระเองทั้งใบ ⇒ อ่านจาก joiner ก่อน ไม่มีค่อย query visit ทีเดียว */
function withInscl(ctx, done) {
	if (Array.isArray(ctx.inscl_hos) && ctx.inscl_hos.length) {
		done(ctx);
		return;
	}
	const form = field.getFormRef();
	form.userState.crudGetAll(
		{
			sdProvider: {
				providerId: VISIT_PROVIDER,
				providerType: 'FORM',
				params: { vid: String(ctx.visit_id) },
				options: { where: "_id = CONVERT(:vid, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => {
			const rec = (res && res.data && res.data[0]) || null;
			ctx.inscl_hos = (rec && rec.inscl_hos) || [];
			done(ctx);
		},
		() => {
			field.alert('อ่านสิทธิ์ของวิสิทไม่สำเร็จ — จอสั่งยาจะคิดเป็นชำระเองทั้งใบ', 'warning');
			done(ctx);
		},
	);
}

// ปุ่ม "+ สั่งยา" ที่หัวการ์ด — เภสัชออกใบเองในนามตัวเอง (b5)
s.ordNew = () => {
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, null));
};

/* ปุ่ม "แก้ใบนี้" — เภสัชแก้ใบของหมอได้เฉพาะก่อนกดจัดยา (b4 · flag can_edit_pis จาก process)
   หลัง prepared ยาจัดลงถุงแล้ว แก้ = ต้องจัดใหม่ ⇒ ปุ่มหายไปเอง ไม่ต้องเช็คสถานะซ้ำที่จอ */
s.ordEdit = (o) => {
	if (!o || !o.order_id) return;
	/* 🔴 `can_edit` (ใบร่าง) กับ `can_edit_pis` (sent/accepted) เป็นคนละกติกา แต่เปิดจอเดียวกัน
	   ใบร่างที่เภสัชกด "+ สั่งยา" แล้วบันทึกไว้เฉย ๆ เคยค้างถาวร — แก้ไม่ได้ ส่งไม่ได้ ลบไม่ได้
	   จากจอห้องยา (ปุ่มส่งอยู่ที่การ์ดหมอในหน้า EMR) ⇒ เจอจริง 2026-09-01 ใบ M2609010001/3
	   ⇒ ให้เปิดกลับเข้าจอสั่งยาได้ แล้วไปกด "ส่งใบสั่งยา" ในจอนั้น
	      (ด่านตรวจยา + กรอกเหตุผล override อยู่ในจอครบแล้ว — ห้ามทำ flow ส่งซ้ำที่การ์ด) */
	if (!o.can_edit_pis && !o.can_edit) {
		field.alert('ใบนี้เลยขั้นจัดยาแล้ว — แก้จากห้องยาไม่ได้', 'warning');
		return;
	}
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, { order_id: String(o.order_id) }));
};

/* ══ ปุ่มบันไดของห้องยา (a3) ══════════════════════════════════════════════
   จัดยา → ชำระ → จ่ายยา · ปุ่มโผล่ทีละขั้นตาม flag ที่ process ตัดสินให้
   🔴 จอไม่คิดกติกาเอง — เงื่อนไขอยู่ที่ cpoe-order-list ที่เดียว (หลักเดียวกับ can_edit ฝั่งหมอ)
      ⇒ วันที่กติกาเปลี่ยน แก้ที่ process จุดเดียว ปุ่มตามเองทุกจอ
   🔴 ทุกปุ่มจบด้วย ordReload() เสมอ แม้ตีกลับ — สถานะจริงอาจถูกอีกจอเปลี่ยนไปแล้ว
      (หมอกดยกเลิกใบ sent วินาทีเดียวกับเภสัชกดจัดยา — process ตัดสินด้วย atomic filter ใครถึงก่อนชนะ) */
const runStage = (o, proc, action, extra) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.ordAct[id]) return; // ใบนี้มี action ค้างอยู่ — กันยิงซ้อนบนสถานะเดิม
	const form = field.getFormRef();
	if (!form) return;
	s.ordAct[id] = action;
	form.userState.runProcess(
		proc,
		Object.assign({ order_id: id }, extra || {}),
		(res) => {
			s.ordAct[id] = '';
			const d = (res && res.data) || {};
			field.alert(d.message || (d.success ? 'ทำรายการแล้ว' : 'ทำรายการไม่สำเร็จ'), d.success ? 'success' : 'warning');
			s.ordReload();
		},
		(err) => {
			s.ordAct[id] = '';
			field.alert('ทำรายการไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
			s.ordReload();
		},
	);
};

/* ══ ใบกำกับการสั่งยา (C18) ═══════════════════════════════════════════════
   เดิมการ์ดขึ้นแค่ป้าย "ยาที่ต้องกำกับ · ตรวจเอกสารให้ครบก่อนจ่าย" ซึ่ง**ไม่มีที่ให้ทำ** —
   เภสัชอ่านแล้วทำอะไรต่อไม่ได้เลย (พี่ท้วง 2026-08-11) · ตัวนี้ต่อป้ายนั้นเข้ากับใบกำกับของจริง

   🔴 เปิดแบบ `readonly` เสมอ — ห้องยามีหน้าที่ **ตรวจ** ใบที่หมอกรอก ไม่ใช่แก้แทนหมอ
      (ถ้าใบผิดต้องให้หมอแก้ หรือย้อนใบด้วยปุ่ม "ย้อนกลับแก้ใบ")
   🔴 override cancelCallback = ต้อง subFormClose() เอง ไม่งั้น popup ค้าง (บทเรียนจาก probe-openform) */
s.ordHasTemp = (it) => !!(it && it.temp_id && it.temp_form_id);
s.ordTempMissing = (it) => !!(it && it.temp_missing);

s.ordViewTemp = (it) => {
	if (!s.ordHasTemp(it)) {
		field.alert('รายการนี้ยังไม่มีใบกำกับให้ดู', 'warning');
		return;
	}
	const form = field.getFormRef();
	if (!form) return;
	form.openForm(String(it.temp_form_id), String(it.temp_id), '', null, {
		readonly: true, // ห้องยาอ่านอย่างเดียว — ใบกำกับเป็นเอกสารของผู้สั่ง
		backdrop: false,
		cancelCallback: () => form.subFormClose(),
	});
};

s.ordBusy = (o) => !!(o && s.ordAct[String(o.order_id)]);
s.ordBusyOn = (o, action) => !!(o && s.ordAct[String(o.order_id)] === action);

// จัดยา — ย้อนกลับไม่ได้ แต่ยังไม่กระทบเงิน/สต็อก ⇒ กดได้เลย ไม่ต้องยืนยัน
s.ordPrepare = (o) => runStage(o, PREPARE_PROC, 'prepare', null);

/* ชำระ — ปุ่มชั่วคราวไว้เทสวงจร (a2 · พี่เคาะ) จอการเงินจริงจะมายิง process ตัวเดียวกันนี้
   ⇒ ถึงเวลาแค่ย้ายปุ่มออก ไม่ต้องรื้อ process · ไม่ส่ง payment_note จากจอนี้ (ไม่ใช่การรับเงินจริง) */
s.ordPay = (o) => runStage(o, PAID_PROC, 'pay', null);

// จ่ายยา — จุดจบของวงจร + ตัดสต็อกจริงที่ process นี้ (C09) ⇒ ของไม่พอจะตีกลับพร้อมบอกว่าขาดอะไร
s.ordDispense = (o) => runStage(o, DISPENSE_PROC, 'dispense', null);

/* ย้อนใบกลับไปแก้ (C17) — ทางออกของใบที่ติดตรงกลาง: จ่ายไม่ได้เพราะของหมด/ยาผิด
   แต่แก้ใบก็ไม่ได้เพราะเลย prepared มาแล้ว (can_edit_pis = false)

   🔴 บังคับกรอกเหตุผล — ใบที่ถอยหลังโดยไม่มีคำอธิบาย ตรวจย้อนหลังไม่ได้ว่าเกิดอะไรขึ้น
      กรอกผ่าน prompt แล้วส่งไปกับ process (server บังคับซ้ำอีกชั้น ไม่เชื่อจอ)
   🔴 ใบที่ชำระเงินแล้ว (ready) เตือนให้ชัดก่อนกด — ย้อนแล้วเงินยังอยู่ในระบบ ต้องให้การเงินตามเก็บ */
s.ordRevert = (o) => {
	if (!o || !o.order_id) return;
	if (!o.can_revert) {
		field.alert('ใบนี้ย้อนกลับไม่ได้', 'warning');
		return;
	}
	const warn = o.paid
		? '\n\n⚠️ ใบนี้ชำระเงินแล้ว (' + s.ordMoney(o.total_amount) + ') — ย้อนแล้วต้องแจ้งการเงินตรวจสอบ'
		: '';
	field.prompt(
		'ย้อนใบ ' + (o.order_number || '') + ' กลับไปสถานะ "ห้องยารับแล้ว" เพื่อแก้ใบ' + warn + '\n\nระบุเหตุผล:',
		(value) => {
			const reason = String(value || '').trim();
			if (!reason) {
				field.alert('ต้องระบุเหตุผล', 'warning');
				return;
			}
			runStage(o, REVERT_PROC, 'revert', { reason: reason });
		},
		{
			inputPlaceholder: 'เช่น ยาหมดคลัง ต้องเปลี่ยนตัวยา',
			inputValidator: (v) => (String(v || '').trim() ? true : 'ต้องระบุเหตุผล'),
		},
		'warning',
		'ย้อนใบกลับไปแก้',
	);
};

/* ══ พิมพ์ฉลากยา — ทั้งใบรวดเดียว (C21 · พี่สั่ง 2026-09-01) ═══════════════
   เดิมเป็นปุ่ม mockup ที่กดแล้วขึ้นข้อความเฉย ๆ · ตอนนี้ต่อกับ report จริงผ่าน <sd-report> ในเทมเพลต
   provider `pis_drug_label` คืน **1 แถว = 1 ดวงฉลาก** (เฉพาะรายการที่เป็นยา) ⇒ กดครั้งเดียวได้ทั้งใบ

   🔴 ฉลากพิมพ์จาก report เท่านั้น — โค้ด event เรียก window/document ไม่ได้ (compileFn ปิด global ชุดนั้น)
   🔴 ปุ่มโผล่ตามสถานะเดียวกับเดิม (จัดยาแล้วขึ้นไป) — ฉลากติดซองต้องออกตอนจัดยาเสร็จ ไม่ใช่ตอนใบยังร่าง
   ⚠️ ยังไม่มี QR/บาร์โค้ดบนดวง — widget qrcode ของ SdReport ผูกกับแถวแรกแถวเดียว ใช้ในตารางที่วนทุกแถวไม่ได้ */
s.ordCanPrint = (o) => {
	const st = String((o && o.current_status) || '');
	if (st !== 'prepared' && st !== 'ready' && st !== 'dispensed') return false;
	return s.ordMedItems(o).length > 0; // ใบที่ไม่มียา ไม่มีอะไรให้ติดซอง
};

// report-list ของ <sd-report> — ก้อนเดียวใช้ทุกใบ (params ต่างหากที่เปลี่ยนตามใบ)
s.ordLabelList = [{ reportId: LABEL_REPORT, label: 'พิมพ์ฉลาก', type: 'pdf' }];
s.ordLabelParams = (o) => ({ order_id: String((o && o.order_id) || '') });

/* ══ รับคืนยาจากคนไข้ (C19) ═══════════════════════════════════════════════
   สองจังหวะเสมอ: กดปุ่ม → ถาม server ว่า "ใบนี้คืนอะไรได้เท่าไหร่" (dry_run) → ค่อยเปิด dialog
   🔴 ไม่ให้จอคิดเพดานเองจาก quantity − returned_qty — ของจริงคืนได้เท่าไหร่อยู่ที่ ledger คลัง
      (ใบอาจถูกกลับรายการ · lot หาย · จ่ายไม่ครบตามใบ) ⇒ ตัวเลขในจอต้องมาจาก server เท่านั้น

   🔴 `return_ref` ออกตอน**เปิด** dialog ไม่ใช่ตอนกดยืนยัน — กดยืนยันรัว/เน็ตหลุดแล้วกดใหม่
      จะได้ ref เดิม ⇒ server ตอบ DUPLICATE ไม่รับของเข้าซ้ำ · ปิด dialog แล้วเปิดใหม่ = ครั้งใหม่จริง ๆ
   🔴 ของที่คืนเข้าคลังเป็น **quarantine** ไม่กลับไปอยู่ในของพร้อมจ่ายทันที — บอกเภสัชให้ชัดใน dialog
      ไม่งั้นเภสัชเข้าใจว่ายากลับไปจ่ายต่อได้เลย แล้วไปงงตอนจ่ายใบถัดไปว่าทำไมของไม่พอ */
s.retOpen = false;
s.retOrder = null;
s.retRows = [];      // รายยา (รวมทุก lot) — เภสัชกรอกจำนวน ส่วนก้อนไหนเป็นเรื่องของ server
s.retReason = '';
s.retRef = '';
s.retLoading = false;

s.ordReturn = (o) => {
	if (!o || !o.order_id) return;
	if (!o.can_return) {
		field.alert('ใบนี้รับคืนจากการ์ดไม่ได้ — รับคืนได้เฉพาะใบที่จ่ายวันนี้', 'warning');
		return;
	}
	const form = field.getFormRef();
	if (!form) return;
	const id = String(o.order_id);
	if (s.ordAct[id]) return;
	s.ordAct[id] = 'return';
	form.userState.runProcess(
		RETURN_PROC,
		{ order_id: id, dry_run: true },
		(res) => {
			s.ordAct[id] = '';
			const d = (res && res.data) || {};
			if (!d.ok) {
				field.alert(d.message || 'ใบนี้รับคืนไม่ได้', 'warning');
				return;
			}
			/* dry_run ตอบมาเป็นราย lot — รวมเป็นรายยาให้เภสัชกรอกง่าย (คนไข้ไม่ได้ถือ lot กลับมาบอก)
			   ยาที่คืนครบแล้วยังโชว์ไว้ แต่กรอกไม่ได้ ⇒ เภสัชเห็นว่า "เคยคืนไปแล้ว" ไม่ใช่หายไปเฉย ๆ */
			const byCode = {};
			const rows = [];
			(d.returnable || []).forEach((x) => {
				if (!byCode[x.item_code]) {
					byCode[x.item_code] = {
						item_code: x.item_code,
						item_name: x.item_name || x.item_code,
						qty_dispensed: 0,
						qty_returned: 0,
						qty_returnable: 0,
						qty: 0,
					};
					rows.push(byCode[x.item_code]);
				}
				byCode[x.item_code].qty_dispensed += Number(x.qty_dispensed) || 0;
				byCode[x.item_code].qty_returned += Number(x.qty_returned) || 0;
				byCode[x.item_code].qty_returnable += Number(x.qty_returnable) || 0;
			});
			if (!rows.length || !rows.some((x) => x.qty_returnable > 0)) {
				field.alert(d.message || 'ใบนี้คืนครบทุกรายการแล้ว', 'info');
				return;
			}
			s.retOrder = o;
			s.retRows = rows;
			s.retReason = '';
			s.retRef = 'R' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36);
			s.retOpen = true;
		},
		(err) => {
			s.ordAct[id] = '';
			field.alert('ตรวจยอดคืนไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

/* 🔴 setter ทุกตัวต้องอยู่ที่นี่ ห้ามใช้ v-model ในเทมเพลต — scope proxy ของ SDCustomContent
   มีแต่ get ไม่มี set trap ⇒ เขียนกลับจากเทมเพลตเมื่อไหร่ **ทั้ง widget กลายเป็นกล่อง error**
   (กติกาเดียวกับ widget-check-rule / widget-allergy-group-pull ที่เจอมาก่อนแล้ว) */
s.retSetOpen = (v) => { if (!v) s.retClose(); };
s.retSetReason = (v) => { s.retReason = String(v == null ? '' : v); };
/* el-input-number คืน null ตอนผู้ใช้ลบค่าในช่อง — ปล่อยผ่านจะได้ NaN ไปโผล่ที่ยอดรวม */
s.retSetQty = (row, v) => {
	const n = Number(v);
	row.qty = isNaN(n) || n < 0 ? 0 : n;
};

s.retTotal = () => s.retRows.reduce((sum, x) => sum + (Number(x.qty) || 0), 0);

s.retClose = () => {
	s.retOpen = false;
	s.retOrder = null;
	s.retRows = [];
	s.retReason = '';
	s.retRef = ''; // ปิดแล้วเปิดใหม่ = การคืนครั้งใหม่ ต้องได้ ref ใหม่ ไม่งั้นจะถูกนับเป็นการกดซ้ำ
};

s.retSubmit = () => {
	const o = s.retOrder;
	if (!o || s.retLoading) return;
	const lines = s.retRows
		.filter((x) => Number(x.qty) > 0)
		.map((x) => ({ item_code: x.item_code, qty: Number(x.qty) }));
	if (!lines.length) {
		field.alert('ยังไม่ได้ใส่จำนวนที่รับคืน', 'warning');
		return;
	}
	const over = s.retRows.filter((x) => Number(x.qty) > Number(x.qty_returnable));
	if (over.length) {
		field.alert('รับคืนเกินที่จ่ายไป: ' + over.map((x) => x.item_name).join(' · '), 'warning');
		return;
	}
	const reason = String(s.retReason || '').trim();
	if (!reason) {
		field.alert('ต้องระบุเหตุผลที่รับคืน', 'warning');
		return;
	}
	const form = field.getFormRef();
	if (!form) return;
	s.retLoading = true;
	form.userState.runProcess(
		RETURN_PROC,
		{ order_id: String(o.order_id), return_ref: s.retRef, reason: reason, lines: lines },
		(res) => {
			s.retLoading = false;
			const d = (res && res.data) || {};
			field.alert(d.message || (d.ok ? 'รับคืนแล้ว' : 'รับคืนไม่สำเร็จ'), d.ok ? 'success' : 'warning');
			// สำเร็จ/ซ้ำ = จบรอบนี้แล้ว ปิด dialog · ล้มเพราะกรอกผิด = คาไว้ให้แก้ต่อโดยไม่ต้องกดใหม่ทั้งชุด
			if (d.ok) s.retClose();
			s.ordReload();
		},
		(err) => {
			s.retLoading = false;
			field.alert('รับคืนไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ PIS mount หลังกด "รับผู้ป่วย"/EMR จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับการ์ดฝั่งหมอ/registry_card)
setTimeout(() => {
	const form = field.getFormRef();
	const tran = form && form.$examTran;
	const visitId = tran && tran.vid && tran.vid.value ? String(tran.vid.value) : null;
	s.ordLoad(visitId, tran || null);
}, 0);

buttonsRow.onClick:
const form = this.getFormRef();
const goEmr = (row) => {
  form.$examTran = row;                                  // opd_card อ่านตอน mount แรก (lazy tab)
  const card = form.getFieldRef('opd_card');
  if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(row);

  const tab = form.getFieldRef('main_app');
  if (tab) tab.activeTabName = 'tab_pane_41691';
};
const st = dataRow.vtran_status;
goEmr(dataRow); return;

options.onScan:
// field: scan_code (scan-code-ui) · onScan(value, qty) — ฟอร์ม EMR
// ยิง HN หรือ VN → ค้น visit tran ของ unit ตัวเอง (วันนี้) → เจอ = สลับไปแท็บ EMR + setTran ให้เลย
// mirror กติกาปุ่ม EMR ในแถวคิวทุกข้อ (called → start ก่อน, waiting/skipped → ไม่ให้เข้า)
// 🔴 ชื่อ param ห้ามเป็น prefix ของกันเอง — ที่นี่ใช้ :scancode ตัวเดียวทั้ง 2 ที่ ปลอดภัย
// 🔴 path ที่มีจุด (`vid.vn`, `vid.pid.hn`) ต้องครอบ backtick ไม่งั้น NoQL อ่านเป็น table.column

const TRAN_FORM  = '6a461235e521219e514d1c4b'   // Visit Tran (zdata_visit_tran)
const VISIT_FORM = '6a40fdec4b6dfdf45acbfbce'   // Visit (zdata_visit)
const START_PROC = '6a4f852422f95f21b606d9a3'   // เริ่มตรวจ (action: 'start')
const TODAY_SQL  = "`visit_date` = DATE_TO_STRING(DATE_ADD(CURRENT_DATE(), 'hour', 7), '%Y-%m-%d')"

const form = this.getFormRef()
const api  = form.userState

if (form.showPopupFlag) return   // มีฟอร์มลูกเปิดค้าง → อย่าสลับคนไข้ข้างหลัง dialog

const code = String(value == null ? '' : value).replace(/\D/g, '')
if (!code) { this.notify('อ่านบาร์โค้ดไม่ได้: ' + value, 'warning'); return }

// ── helper: ยิง query แล้วรอผลให้จบทางเดียว (callback/promise แล้วแต่จังหวะ) + กันค้าง 5 วิ ──
const runQuery = (sdProvider) => new Promise((resolve) => {
  let settled = false
  const done = (r) => { if (!settled) { settled = true; resolve(r) } }
  let ret
  try { ret = api.crudGetAll({ sdProvider, totalEnable: false }, (r) => done(r), () => done(null)) }
  catch (e) { done(null); return }
  if (ret && typeof ret.then === 'function') ret.then((r) => { if (r !== undefined && r !== null) done(r) }).catch(() => {})
  setTimeout(() => done(null), 5000)
})
const pickRows = (r) => {
  if (!r) return []
  if (Array.isArray(r)) return r
  if (Array.isArray(r.data)) return r.data
  if (r.data && Array.isArray(r.data.data)) return r.data.data
  if (r.reply && Array.isArray(r.reply.data)) return r.reply.data
  if (Array.isArray(r.rows)) return r.rows
  return []
}

// ── ① ค้น visit tran ทั้ง unit ของเราวันนี้ (ทุกสถานะ รวม done) ด้วย VN หรือ HN ──
// ไม่ระบุ select เพื่อให้ได้ vid.* ที่ join มาครบเหมือนที่ list ส่งให้ปุ่ม EMR (setTran ต้องใช้)
const rows = pickRows(await runQuery({
  providerId: TRAN_FORM,
  providerType: 'FORM',
  options: {
    where: TODAY_SQL + ' AND `unit_to.value` = :xunit_codex AND (`vid.vn` = :scancode OR `vid.pid.hn` = :scancode)',
    orderBy: [{ column: 'queue_ts', sort: 'DESC' }],
    limit: 10,
  },
  params: { scancode: code },
}))

// ── ② ไม่มีคิว → บอกให้ได้ว่า "ไม่มี visit" หรือ "มี visit แต่คิวพัง" ──
if (!rows.length) {
  const vrows = pickRows(await runQuery({
    providerId: VISIT_FORM,
    providerType: 'FORM',
    options: {
      where: TODAY_SQL + ' AND (`vn` = :scancode OR `pid.hn` = :scancode)',
      select: ['_id', 'vn', 'pid'],
      limit: 3,
    },
    params: { scancode: code },
  }))
  if (vrows.length) {
    const v = vrows[0]
    const p = v.pid || {}
    this.notify('พบ visit VN' + (v.vn || '-') + ' (HN' + (p.hn || '-') + ' ' + ((p.p_fname || '') + ' ' + (p.p_lname || '')).trim() + ') แต่ไม่มีคิวในหน่วยนี้วันนี้', 'warning')
  } else {
    this.notify('ไม่พบ HN/VN ' + code + ' ในระบบวันนี้', 'warning')
  }
  return
}

// ── ③ เลขเดียวไปตรงกับคนละคน (VN ของคนหนึ่ง = HN ของอีกคน) → ไม่เดา ให้เลือกจากคิวเอง ──
const visitIds = []
rows.forEach((r) => {
  const vidVal = r.vid && r.vid.value ? String(r.vid.value) : ''
  if (vidVal && visitIds.indexOf(vidVal) === -1) visitIds.push(vidVal)
})
if (visitIds.length > 1) {
  const who = rows.map((r) => {
    const p = (r.vid && r.vid.pid) || {}
    return 'VN' + ((r.vid && r.vid.vn) || '-') + '/HN' + (p.hn || '-') + ' ' + (p.p_fname || '')
  }).join(' · ')
  this.notify('รหัส ' + code + ' ตรงกับหลายราย: ' + who + ' — กรุณาเลือกจากคิวเอง', 'warning')
  return
}

// ── ④ คนเดียวหลายคิว → ห้องฉันก่อน แล้วสถานะที่กำลังทำอยู่ก่อน ──
const RANK = { in_progress: 4, called: 3, waiting: 2, skipped: 1, done: 0 }
const myRoom = (api.user && api.user.room && api.user.room.code) || ''
const score = (r) =>
  (myRoom && r.room_to && String(r.room_to.value) === String(myRoom) ? 100 : 0) +
  (RANK[r.vtran_status] != null ? RANK[r.vtran_status] : 0)
rows.sort((a, b) => score(b) - score(a) || String(b.queue_ts || '').localeCompare(String(a.queue_ts || '')))
const tran = rows[0]

const pt   = (tran.vid && tran.vid.pid) || {}
const name = ((pt.p_fname || '') + ' ' + (pt.p_lname || '')).trim()
const tag  = 'คิว ' + (tran.queue_label || '-') + ' · HN' + (pt.hn || '-') + ' ' + name

// ── ⑤ เข้า EMR — 3 บรรทัดเดียวกับปุ่ม EMR ในแถวคิว ──
const goEmr = (row) => {
  form.$examTran = row                                   // opd_card อ่านตอน mount แรก (lazy tab)
  const card = form.getFieldRef('opd_card')
  if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(row)
  const tab = form.getFieldRef('main_app')
  if (tab) tab.activeTabName = 'tab_pane_41691'
}
const refreshQueues = () => {
  ;['visit_unit', 'visit_room'].forEach((n) => {
    const ref = form.getFieldRef(n)
    const ed  = ref && ref.getFieldEditor && ref.getFieldEditor()
    if (ed && ed.handleRefresh) ed.handleRefresh()
  })
}

const st = tran.vtran_status

if (st === 'in_progress') { goEmr(tran); this.notify('เข้า EMR ' + tag, 'success'); return }

if (st === 'done') { goEmr(tran); this.notify('เข้า EMR ' + tag + ' — ⚠ คิวนี้ปิดตรวจแล้ว', 'warning'); return }

if (st !== 'called') {
  this.notify('คิวยังไม่ถูกเรียก (สถานะ: ' + (st || '-') + ') — ' + tag, 'warning')
  return
}

// called → เริ่มตรวจให้เหมือนกดปุ่ม EMR แล้วค่อยเข้า
api.runProcess(START_PROC, { tran_id: String(tran._id), action: 'start' }, (res) => {
  const d = res.data || {}
  if (!d.success) { this.alert(d.message || 'เริ่มตรวจไม่สำเร็จ', 'warning'); return }
  this.notify('เริ่มตรวจ ' + tag, 'success')
  refreshQueues()
  // process เพิ่ง stamp start_at ใน DB — tran เป็น snapshot เก่า ต้อง patch ก่อนส่งเข้าการ์ด ไม่งั้น timer ขึ้น --:--
  goEmr({ ...tran, vtran_status: 'in_progress', start_at: this.dayjs().format('YYYY-MM-DD HH:mm:ss') })
}, (err) => this.alert(String((err && err.message) || err), 'error'))

